pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(address log1, address log2) internal {
        vm.assume(true);
        bool reverted1;
        try c.SetLogFile(log1) { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.SetLogFile(log2) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 && !reverted2);
    }

    function testFuzz_run(address log1, address log2) public {
        vm.assume(log1.code.length == 0 && uint160(log1) > 0xffff && log1 != address(this) && log1 != address(c) && log1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log1 != 0x000000000000000000636F6e736F6c652e6c6f67 && log1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(log2.code.length == 0 && uint160(log2) > 0xffff && log2 != address(this) && log2 != address(c) && log2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log2 != 0x000000000000000000636F6e736F6c652e6c6f67 && log2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(log1, log2);
    }

    receive() external payable {}
}
